"""Count word frequencies in a text file and report the most common words."""

import re
import sys

# Letters and digits, no underscores, Unicode-aware.
WORD_RE = re.compile(r"[^\W_]+")


def top_words(path, n=10):
    """Return the n most common (word, count) pairs, most frequent first.

    Words are matched case-insensitively with surrounding punctuation removed.
    Ties are broken alphabetically so the output is deterministic.
    """
    counts = {}
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            for w in WORD_RE.findall(line.lower()):
                counts[w] = counts.get(w, 0) + 1
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if not argv:
        print("usage: wordfreq.py PATH [N]", file=sys.stderr)
        return 2
    path = argv[0]
    try:
        n = int(argv[1]) if len(argv) > 1 else 10
    except ValueError:
        print("error: N must be an integer", file=sys.stderr)
        return 2
    if n < 0:
        print("error: N must be non-negative", file=sys.stderr)
        return 2
    try:
        results = top_words(path, n)
    except OSError as exc:
        print(f"error: cannot read {path}: {exc}", file=sys.stderr)
        return 1
    for word, count in results:
        print(word, count)
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Tests for src/wordfreq.py."""

import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src"))

import wordfreq  # noqa: E402

SAMPLE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "sample.txt")


class TopWordsTest(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)

    def write(self, text, name="t.txt"):
        path = os.path.join(self._tmp.name, name)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text)
        return path

    def test_orders_most_frequent_first(self):
        path = self.write("a a a b b c")
        self.assertEqual(wordfreq.top_words(path), [("a", 3), ("b", 2), ("c", 1)])

    def test_case_insensitive(self):
        path = self.write("The the THE tHe")
        self.assertEqual(wordfreq.top_words(path), [("the", 4)])

    def test_strips_punctuation(self):
        path = self.write("hat. hat, hat; (hat)! hat?")
        self.assertEqual(wordfreq.top_words(path), [("hat", 5)])

    def test_ties_broken_alphabetically(self):
        path = self.write("zebra apple mango")
        self.assertEqual(
            wordfreq.top_words(path), [("apple", 1), ("mango", 1), ("zebra", 1)]
        )

    def test_respects_n_limit(self):
        path = self.write("a a a b b c")
        self.assertEqual(wordfreq.top_words(path, 2), [("a", 3), ("b", 2)])

    def test_default_n_is_ten(self):
        path = self.write(" ".join(f"w{i}" for i in range(25)))
        self.assertEqual(len(wordfreq.top_words(path)), 10)

    def test_empty_file(self):
        self.assertEqual(wordfreq.top_words(self.write("")), [])

    def test_sample_file(self):
        self.assertEqual(
            wordfreq.top_words(SAMPLE, 3),
            [("the", 4), ("cat", 2), ("hat", 2)],
        )

    def test_missing_file_raises_oserror(self):
        with self.assertRaises(OSError):
            wordfreq.top_words(os.path.join(self._tmp.name, "nope.txt"))

    def test_utf8_content(self):
        path = self.write("café café naïve")
        self.assertEqual(wordfreq.top_words(path), [("café", 2), ("naïve", 1)])


class MainTest(unittest.TestCase):
    def test_missing_path_returns_usage_error(self):
        self.assertEqual(wordfreq.main([]), 2)

    def test_non_integer_n_returns_error(self):
        self.assertEqual(wordfreq.main([SAMPLE, "many"]), 2)

    def test_missing_file_returns_error(self):
        self.assertEqual(wordfreq.main(["/nonexistent/x.txt"]), 1)

    def test_success_returns_zero(self):
        self.assertEqual(wordfreq.main([SAMPLE]), 0)


if __name__ == "__main__":
    unittest.main()
